def simulate_perfect_swing(
    candles: list[dict],
    fee_rate: float,
    capital: float,
    lot: int,
    min_move_pct: float,
    slippage: float,
    multiday: bool = False,
) -> dict:
    """Идеальный свинг-трейдер: покупает на каждой подтверждённой волне зигзага."""
    if multiday:
        groups: list[list[dict]] = [candles]
    else:
        groups = []
        for c in candles:
            if not groups or groups[-1][0]["ts"][:10] != c["ts"][:10]:
                groups.append([])
            groups[-1].append(c)

    trades: list[dict] = []
    for g in groups:
        swings = zigzag_swings(g, min_move_pct)
        if not swings:
            continue
        if swings[0]["kind"] == "high":
            swings = swings[1:]
        pos = 0
        entry_px = None
        entry_ts = None
        cash = capital
        for sw in swings:
            px = sw["price"]
            ts = g[sw["idx"]]["ts"]
            if sw["kind"] == "low" and pos == 0:
                lots = int(cash / (px * (1 + slippage) * lot * (1 + fee_rate)))
                if lots > 0:
                    pos = lots
                    cash -= lots * lot * px * (1 + slippage) * (1 + fee_rate)
                    entry_px, entry_ts = px, ts
            elif sw["kind"] == "high" and pos > 0:
                exit_px = px
                cash += pos * lot * exit_px * (1 - slippage) * (1 - fee_rate)
                pnl = pos * lot * (
                    exit_px * (1 - slippage) * (1 - fee_rate)
                    - entry_px * (1 + slippage) * (1 + fee_rate)
                )
                trades.append(
                    {
                        "entry_ts": entry_ts,
                        "exit_ts": ts,
                        "entry_px": entry_px,
                        "exit_px": exit_px,
                        "pnl": round(pnl, 2),
                        "lots": pos,
                    }
                )
                pos = 0
        if pos > 0:
            close_px = float(g[-1]["close"])
            cash += pos * lot * close_px * (1 - slippage) * (1 - fee_rate)
            pnl = pos * lot * (
                close_px * (1 - slippage) * (1 - fee_rate)
                - entry_px * (1 + slippage) * (1 + fee_rate)
            )
            trades.append(
                {
                    "entry_ts": entry_ts,
                    "exit_ts": g[-1]["ts"],
                    "entry_px": entry_px,
                    "exit_px": close_px,
                    "pnl": round(pnl, 2),
                    "lots": pos,
                    "open": True,
                }
            )
    total_pnl = sum(t["pnl"] for t in trades)
    return {"trades": trades, "pnl": round(total_pnl, 2)}

