def _signal_quality(role: str, strategy_id: str, tf: str, signals: list[dict],
                    oracle_points: dict[str, list[datetime]], window_min: int) -> dict:
    """Покрытие/точность сигналов функции против точек оракула того же направления."""
    for side in ("BUY", "SELL"):
        hits, lead = 0, []
        total = len(signals)
        false_pos = 0
        for s in signals:
            if s["side"] != side:
                continue
            best = min((abs((s["ts"] - p).total_seconds()) for p in oracle_points[side]), default=None)
            if best is not None and best <= window_min * 60:
                hits += 1
                lead.append((s["ts"] - min(oracle_points[side], key=lambda p: abs((s["ts"] - p).total_seconds()))).total_seconds() / 60)
            else:
                false_pos += 1
        cov = hits / max(len(oracle_points[side]), 1) * 100
        prec = hits / max(total, 1) * 100
        lead_med = sorted(lead)[len(lead) // 2] if lead else None
        return {
            "role": role, "strategy_id": strategy_id, "tf": tf, "side": side,
            "signals": total, "oracle_points": len(oracle_points[side]),
            "hits": hits, "coverage_pct": round(cov, 1), "precision_pct": round(prec, 1),
            "lead_min_median": round(lead_med, 1) if lead_med is not None else None,
            "false_positives": false_pos,
        }
    return {"role": role, "strategy_id": strategy_id, "tf": tf, "side": "?", "signals": 0,
            "coverage_pct": 0.0, "precision_pct": 0.0, "lead_min_median": None, "false_positives": 0}

