def _oracle_fixed_qty(candles: list[EngineCandle], threshold_pct: float, fee_rate: float,
                      qty_shares: float, lot: int) -> dict:
    """Идеальный свинг (зигзаг) с ФИКСИРОВАННЫМ размером позиции — сопоставим с движком."""
    swings = zigzag_swings([c.__dict__ for c in candles], threshold_pct / 100.0)
    trades: list[dict] = []
    for k in range(len(swings) - 1):
        sw, nxt = swings[k], swings[k + 1]
        if sw["kind"] != "low":
            continue
        entry_px, exit_px = sw["price"], nxt["price"]
        gross = (exit_px - entry_px) * qty_shares
        commission = (entry_px + exit_px) * qty_shares * fee_rate
        trades.append({
            "entry_ts": candles[sw["idx"]]["ts"].isoformat() if isinstance(candles[sw["idx"]].ts, datetime) else str(candles[sw["idx"]].ts),
            "exit_ts": candles[nxt["idx"]]["ts"].isoformat() if isinstance(candles[nxt["idx"]].ts, datetime) else str(candles[nxt["idx"]].ts),
            "entry_px": round(entry_px, 6),
            "exit_px": round(exit_px, 6),
            "gross": round(gross, 2),
            "commission": round(commission, 2),
            "net": round(gross - commission, 2),
        })
    return {"trades": trades, "gross": round(sum(t["gross"] for t in trades), 2),
            "net": round(sum(t["net"] for t in trades), 2)}

