    </tr>`).join("");
  if (useless.size > 0) {
    $("ens-quality").innerHTML += `<tr><td colspan="8" class="num">Бесполезные (coverage=0): ${[...useless].join(", ")}</td></tr>`;
  }

  const ec = d.economicRow ?? null;
