import re
html = open("index.html", encoding="utf-8").read()
lines = html.split("\n")
stack = []
start = None
for i, line in enumerate(lines):
    if 'class="bottom-panel"' in line:
        start = i; break
print("bottom-panel:", start+1)
stack = []
for i in range(start, start+25):
    line = lines[i]
    for m in re.finditer(r'<div\b([^>]*?)(/?)>', line):
        if not m.group(2):
            mid = re.search(r'id="([^"]+)"', m.group(1))
            stack.append((i+1, mid.group(1) if mid else None))
    for m in re.finditer(r'</div>', line):
        if stack: stack.pop()
        else: print(f"строка {i+1}: лишнее </div>")
print("незакрытые в области:", stack)
# общий баланс
print("div open:", len(re.findall(r'<div\b', html)), "| close:", len(re.findall(r'</div>', html)))
print("section open:", len(re.findall(r'<section\b', html)), "| close:", len(re.findall(r'</section>', html)))
EOF

