// ============ Очередь ансамблевых прогонов (Lab → Ансамбль) ============

export interface EnsembleLabRun {
  run_id: string;
  status: string;
  params: Record<string, unknown>;
  progress: {
    done: number;
    total: number;
    current: string;
    by_stock: Record<string, { done: number; total: number }>;
