function verdictBadge(v: string): string {
  return `<span class="verdict-badge v-${v.toLowerCase()}">${v}</span>`;
}

function collectUniverseTickers(): string[] {
  const chips = document.querySelectorAll<HTMLButtonElement>("#el-figis .chip.selected");
  if (chips.length) return [...chips].map((c) => c.textContent!.trim());
  return ["RUAL", "AFLT", "SNGSP", "MVID", "NLMK"];
}

function universeFromConfig(c: any): string[] | null {
  const filters = (c?.filters ?? []) as Array<{ id?: string; params?: Record<string, unknown> }>;
  const u = filters.find((f) => f.id === "universe");
  const tk = u?.params?.tickers;
  return Array.isArray(tk) && tk.length ? (tk as string[]) : null;
}

