      </thead>
      <tbody>${stockRows || `<tr><td colspan="9" class="mini-hint">ожидание данных прогона…</td></tr>`}</tbody>
    </table>` + summary;
}

function sumBy(arr: any[], fn: (x: any) => number): number {
  return arr.reduce((s, x) => s + (fn(x) ?? 0), 0);
}

