  if (x1 === null && x2 === null) continue;
  const left = x1 ?? 0;
  const right = x2 ?? scope.mediaSize.width;
  ctx.fillStyle = z.win ? "rgba(38,166,154,0.14)" : "rgba(239,83,80,0.16)";
  ctx.fillRect(left, 0, Math.max(2, right - left), scope.mediaSize.height);
}

