    const a = toUnix(fromTs);
    const b = toUnix(toTs) || a + 3600;
    const pad = Math.max(60, (b - a) * 0.15);
    try {
      chart.timeScale().setVisibleLogicalRange({ from: a - pad, to: b + pad } as never);
